mapper.update:

UPDATE ICOMECCT
SET
	CONT_STATUS		= #{contStatus}
	,CHANGE_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD')
	,CHANGE_TIME		= TO_CHAR(SYSDATE,'HH24MISS')
	,CHANGE_USER_ID	= #{st_user_id}
WHERE CONT_NO		= #{st_cont_no}
AND CONT_COUNT		= #{st_cont_count}


UPDATE ICOMECCT
SET
	CLOSE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	,CLOSE_REASON		= #{st_reason}
	,CONT_STATUS		= #{contStatus}
	,CHANGE_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD')
	,CHANGE_TIME		= TO_CHAR(SYSDATE,'HH24MISS')
	,CHANGE_USER_ID	= #{st_user_id}
WHERE CONT_NO		= #{st_cont_no}
AND CONT_COUNT		= #{st_cont_count}


UPDATE ICOMCMPY
SET
	CNTRC_CHK					= 'Y'
	,ELCTR_CNTRC_NO			= #{st_cont_no}
	,ELCTR_CNTRC_NO_RND	= #{st_cont_count}
	,CHANGE_DATE				= TO_CHAR(SYSDATE,'YYYYMMDD')
	,CHANGE_TIME				= TO_CHAR(SYSDATE,'HH24MISS')
	,CHANGE_USER_ID			= #{st_user_id}
WHERE COM_CODE				= #{st_company_code}


INSERT INTO ICOMECSV (
	CONT_NO
	,CONT_COUNT
	,SIGN_SEQ
	,DOC_TYPE
	,SIGN_SOURCE
	,SIGN_VALUE
	,SIGN_COMPANY_ID
	,SIGN_USER_ID
	,SIGN_DATE
	,REL_FORM_NO
	,REL_RFORM_NO
	,REL_ATACH_UUID
	,REL_ATACH_UUID_SEQ
	,PREV_CONT_STATUS
	,NEXT_CONT_STATUS
	,ADD_DATE
	,ADD_TIME
	,ADD_USER_ID
	,CHANGE_DATE
	,CHANGE_TIME
	,CHANGE_USER_ID
) VALUES (
	#{st_cont_no}
	,#{st_cont_count}
	,(SELECT NVL(MAX(TO_NUMBER(SIGN_SEQ)), 0) + 1 AS MAX_CNT FROM ICOMECSV WHERE CONT_NO = #{st_cont_no} AND CONT_COUNT = #{st_cont_count})
	,#{st_doc_type}
	,#{st_sign_source}
	,#{st_sign_value}
	,#{st_com_code}
	,#{st_user_id}
	,TO_CHAR(SYSDATE,'YYYYMMDD')
	,#{st_form_no}
	,''
	,''
	,''
	,#{st_cont_status}
	,#{nextContStatus}
	,TO_CHAR(SYSDATE,'YYYYMMDD')
	,TO_CHAR(SYSDATE,'HH24MISS')
	,#{st_user_id}
	,TO_CHAR(SYSDATE,'YYYYMMDD')
	,TO_CHAR(SYSDATE,'HH24MISS')
	,#{st_user_id}
)
